-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: UPDATE transformation_levers SET status = 'session', landed_at = NULL, note = 'needs a session: a repo lever: not a single-file edit' WHERE tp = 3 AND n = 9 AND note LIKE 'C5-RESILIENCE:%'; UPDATE transformation_levers SET note = substr(note, 1, instr(note, ' || C5-RESILIENCE-TP3B ') - 1) WHERE tp = 3 AND n = 8 AND instr(note, ' || C5-RESILIENCE-TP3B ') > 0; DELETE FROM agent_issues WHERE source = 'session:c5-resilience' AND title LIKE 'ROADMAP-1: QNFO.INFRA TP-3_-%'; UPDATE roadmap_implementation SET evidence = substr(evidence, 1, instr(evidence, ' || C5-RESILIENCE-128 ') - 1) WHERE id = 128 AND instr(evidence, ' || C5-RESILIENCE-128 ') > 0;
-- BACKUP: agent_issues

UPDATE transformation_levers
SET status = 'landed', landed_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now'),
    note = 'C5-RESILIENCE: scripts/charter-guard.py check C6 fails a live worker directory that declares no "# charter-pillar: <key>" in its wrangler.toml. Read 2026-11-05 ~00:30Z: 36 directories have a wrangler.toml and no RETIRED or FOLDED marker, and 0 of them lack the line (agent_issues 1001461 is closed).'
WHERE tp = 3 AND n = 9 AND status = 'session';

UPDATE transformation_levers
SET note = COALESCE(note, '') || ' || C5-RESILIENCE-TP3B 2026-11-05: the applier half is done (TP-3a, 35 workflows) and TP-3b deleted 5 spent attach-* workflows (archive/ATTACH-WORKFLOWS-MANIFEST.md); the other half of this lever, moving the 64 RETIRED and FOLDED worker directories under archive/, is open as TP-3D-ARCHIVE-DEAD-DIRS-1.'
WHERE tp = 3 AND n = 8 AND instr(COALESCE(note, ''), 'C5-RESILIENCE-TP3B') = 0;

INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
SELECT 'ROADMAP-1: QNFO.INFRA TP-3B-ATTACH-1: three attach workflows last ran failed or rolled back (ask-qwav redirect, lifecycle fallback route, surface routes)',
 'QNFO.INFRA; charter pillar core; roadmap row RM-TP-3-FOOTPRINT-TEARDOWN (workflow count 71 against the exit of 25). archive/ATTACH-WORKFLOWS-MANIFEST.md (TP-3b) deleted the 5 attach-* route workflows whose last ci-status result is ok and whose host answers from outside, and kept three whose last result is not ok: attach-ask-qwav-route (ci-status/attach-ask-qwav-route.json: stage redirect, status failed, 2026-11-01T17:19:57Z; ask.qwav.org answers 200 but ask.qwav.tech still answers 200 where the script definition of done is a 301 to ask.qwav.org), attach-lifecycle-custom-domain (stage fallback-route, status failed, 2026-11-01T17:19:28Z; lifecycle.qnfo.org answers 200) and attach-surface-routes (qwav.tech route created, not verified, rolled back; archive.qnfo.org present and verified; www.qwav.org and qwav.tech answer 301 to qwav.org). Work, per workflow: read its script and the ci-status record, decide whether the host is served some other way now (then retire the workflow with that evidence, as the manifest does) or finish the stage that failed (then it is spent and joins the manifest). For ask-qwav the open stage is attach_tech_redirect: a Single Redirect rule on the qwav.tech zone from ask.qwav.tech to https://ask.qwav.org with the path and query kept, which the repository CLOUDFLARE_API_TOKEN can write (docs: a token that writes zone routes and DNS). Deleting a workflow is a pull request that changes .github/workflows: the stale-PR lane merges it (ops_config stale_pr_merge_workflows on), the code loop cannot. Prediction: workflow files 71 to 68 and no attach-* workflow whose last run failed. Closing marker: the change carries the text TP-3B-ATTACH-1.' || char(10) ||
 'code-task: repo=qnfo-workers path=scripts/attach-ask-qwav-route.py' || char(10) ||
 'code-anchor: def attach_tech_redirect(zone):' || char(10) ||
 'code-probe: {"paths":["scripts/attach-ask-qwav-route.py"],"contains":"TP-3B-ATTACH-1"}',
 'session:c5-resilience', 'code', 'medium', 'open', unixepoch() * 1000, unixepoch() * 1000
WHERE NOT EXISTS (SELECT 1 FROM agent_issues WHERE instr(title, 'ROADMAP-1: QNFO.INFRA TP-3B-ATTACH-1:') = 1 AND status = 'open');

INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
SELECT 'ROADMAP-1: QNFO.INFRA TP-3C-D1-FOLD-1: fold the qnfo-cms database into qnfo-audit and delete it (d1 10 to 9, T3 lever 6)',
 'QNFO.INFRA; charter pillar core; roadmap row RM-TP-3-FOOTPRINT-TEARDOWN (D1 databases 10 against the exit of 8; qnfo-cms and portfolio-state are the two the program names). Read 2026-11-05 ~00:30Z: qnfo-cms (id 0458a344-090d-4264-a0e0-c95d7fa237f3) holds 7 tables and 196608 bytes: content_types 5 rows, content_entries 145, authors 1, categories 8, content_relationships 33, publish_queue 8, content 0. fleet-graph resource d1:qnfo-cms shows one binder, qnfo-ops QNFO_CMS (the fleet-exec CMS binding is in a FOLDED directory). qnfo-ops reaches it through the db alias cms (DB_MAP; the wrangler comment calls it read-only via ops_d1_query, and the system map counts qnfo-ops as its one writer because the alias is generic), so the fold must first prove from the ops audit trail that no tool call named db cms in 30 days. The standing grant (OWNER-STANDING-GRANT-1) allows deleting an unused D1 database after a verified backup (D1-FOLD-1: cf-ops-actions d1-backup, unbind-d1, delete-d1). Work: (1) run fleet-graph impact on d1:qnfo-cms, git grep qnfo-cms and QNFO_CMS, and read the ops_ai_tool events of 30 days for a call with db cms (an indexed read by kind and ts) first; (2) copy the 7 tables into qnfo-audit as cms_content_types, cms_content_entries and so on from the newest ok R2 export (scripts/d1_restore_drill.py already reads those exports) by a migration with row counts that match the numbers above, keeping the export; (3) in qnfo-ops remove the QNFO_CMS binding from wrangler.toml, the cms entry from DB_MAP and the bindings.d1.cms line of /health, and point any caller of the alias at the cms_ tables in audit; remove qnfo-cms from scripts/continuity_snapshot.py and DRILL_EXPORTS in scripts/d1_restore_drill.py and re-point migrations/fm-d1-export-stale-probe; (4) run d1-backup, unbind-d1 and delete-d1 through cf-ops-actions after the deploy is verified. qnfo-ops is control plane (a pull request with a work claim, a version bump, the canary); its worker.js was held by C-ops-tools when this was written, so take the claim over when it lapses. Note D1-SPLIT-1 (agent_issues 1001778 to 1001780 and 1001816) adds databases (qnfo-telemetry and a hot-table database): the exit of 8 needs both directions decided together, so state the net count in the pull request. Prediction: the account D1 list reads 9 databases, qnfo-audit gains 7 small tables and 196 KB. Closing marker: the change carries the text TP-3C-D1-FOLD-1.' || char(10) ||
 'code-task: repo=qnfo-workers path=qnfo-ops/worker.js' || char(10) ||
 'code-anchor: var DB_MAP = { audit: "QNFO_AUDIT", living: "LIVING_PAPER", graph: "QNFO_GRAPH",' || char(10) ||
 'code-probe: {"paths":["qnfo-ops/worker.js"],"contains":"TP-3C-D1-FOLD-1"}',
 'session:c5-resilience', 'code', 'medium', 'open', unixepoch() * 1000, unixepoch() * 1000
